import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int N = Integer.parseInt(st.nextToken());
        int F = Integer.parseInt(st.nextToken());

        char[][] grid = new char[N][];
        for (int i = 0; i < N; i++) {
            grid[i] = br.readLine().toCharArray();
        }

        if (grid[0][0] - '0' <= F) {
            boolean[][] visited = new boolean[N][N];
            int[] queueR = new int[N * N];
            int[] queueC = new int[N * N];

            int head = 0, tail = 0;
            queueR[tail] = 0;
            queueC[tail] = 0;
            tail++;
            visited[0][0] = true;
            grid[0][0] = '*';

            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};

            while (head < tail) {
                int r = queueR[head];
                int c = queueC[head];
                head++;

                for (int k = 0; k < 4; k++) {
                    int nr = r + dr[k];
                    int nc = c + dc[k];

                    if (nr >= 0 && nr < N && nc >= 0 && nc < N &&
                        !visited[nr][nc] && grid[nr][nc] - '0' <= F) {
                        visited[nr][nc] = true;
                        grid[nr][nc] = '*';
                        queueR[tail] = nr;
                        queueC[tail] = nc;
                        tail++;
                    }
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < N; i++) {
            sb.append(grid[i]).append('\n');
        }

        System.out.print(sb);
    }
}
